type ValidationExceptionFieldCode string

// Enum values for ValidationExceptionFieldCode
const (
	// The value is shorter than the field's MinLength .
	ValidationExceptionFieldCodeValueTooShort ValidationExceptionFieldCode = "VALUE_TOO_SHORT"
	// The value is longer than the field's MaxLength .
	ValidationExceptionFieldCodeValueTooLong ValidationExceptionFieldCode = "VALUE_TOO_LONG"
	// The value does not match the field's Pattern .
	ValidationExceptionFieldCodePatternMismatch ValidationExceptionFieldCode = "PATTERN_MISMATCH"
	// A rich-text value carries a tag outside the field's AllowedTags .
	ValidationExceptionFieldCodeDisallowedHtmlTag ValidationExceptionFieldCode = "DISALLOWED_HTML_TAG"
	// The value's kind does not match the field's kind — text supplied for an image
	// field, or an ImageReference or CampaignAssetImage supplied for a text field.
	ValidationExceptionFieldCodeWrongValueType ValidationExceptionFieldCode = "WRONG_VALUE_TYPE"
	// A staged-file reference — an image field's value, EmailTarget , or any other
	// member taking a staged upload — is not usable: not an s3:// URI, malformed,
	// missing its VersionId , naming a bucket that is not the Partner Central file
	// staging bucket, or naming no file at that key and version. For an image field,
	// also a URL that is not a suggested image Build with AI returned, including a URL
	// a read returned.
	ValidationExceptionFieldCodeFileReferenceInvalid ValidationExceptionFieldCode = "FILE_REFERENCE_INVALID"
	// The staged path is under a different AWS account id than the caller's. Its own
	// code rather than FILE_REFERENCE_INVALID because the fix differs: the reference
	// is well formed, it just is not yours.
	ValidationExceptionFieldCodeFileReferenceNotOwned ValidationExceptionFieldCode = "FILE_REFERENCE_NOT_OWNED"
	// The file's extension is not an image format this service accepts.
	ValidationExceptionFieldCodeImageFormatNotSupported ValidationExceptionFieldCode = "IMAGE_FORMAT_NOT_SUPPORTED"
	// The file is an image, but not one this field's AllowedFormats permits.
	ValidationExceptionFieldCodeImageFormatNotAllowed ValidationExceptionFieldCode = "IMAGE_FORMAT_NOT_ALLOWED"
	// The file is larger than this field's MaxSizeBytes .
	ValidationExceptionFieldCodeImageTooLarge ValidationExceptionFieldCode = "IMAGE_TOO_LARGE"
	// A non-image file is larger than the service accepts — today only a campaign's
	// recipient list.
	ValidationExceptionFieldCodeFileTooLarge ValidationExceptionFieldCode = "FILE_TOO_LARGE"
	// The content scan declined the file. The field keeps the value it already had;
	// supply a different file.
	ValidationExceptionFieldCodeScanRejected ValidationExceptionFieldCode = "SCAN_REJECTED"
	// No field of this name exists in the asset's pinned schema. Also returned for a
	// field the service fills itself, such as an email's fixed link to its landing
	// page: such a field is never listed.
	ValidationExceptionFieldCodeUnknownField ValidationExceptionFieldCode = "UNKNOWN_FIELD"
	// The image's shape is too far from the slot's recommended size to fill it. A
	// document image slot that declares RecommendedWidthPixels and
	// RecommendedHeightPixels is filled and clipped, so a much taller or wider image
	// would lose most of its content. Supply an image close to the size the message
	// names.
	ValidationExceptionFieldCodeImageAspectRatioMismatch ValidationExceptionFieldCode = "IMAGE_ASPECT_RATIO_MISMATCH"
	// The field shows a campaign setting, named by the field's CampaignSetting , so
	// its value comes from the campaign and an asset cannot override it. Change it
	// with UpdateCampaign instead.
	ValidationExceptionFieldCodeFieldSetOnCampaign ValidationExceptionFieldCode = "FIELD_SET_ON_CAMPAIGN"
	// A campaign's recipient list has no header row naming the email column. Name it
	// Email , E-mail , Email Address or E-mail Address ; case, spaces and punctuation
	// do not matter.
	ValidationExceptionFieldCodeEmailColumnMissing ValidationExceptionFieldCode = "EMAIL_COLUMN_MISSING"
	// A campaign's recipient list carries more than 10,000 distinct addresses.
	ValidationExceptionFieldCodeRecipientListTooLarge ValidationExceptionFieldCode = "RECIPIENT_LIST_TOO_LARGE"
	// A campaign's recipient list holds no valid email address — an empty file, a
	// header with no rows, or rows that all fail the address format check.
	ValidationExceptionFieldCodeRecipientListEmpty ValidationExceptionFieldCode = "RECIPIENT_LIST_EMPTY"
	// The value is not one this member accepts: a Layout naming none of the asset's
	// layout options, an AssetLink value naming no asset of the field's category on
	// this campaign, or a SendMode and ScheduledSendAt that disagree (the entry names
	// the member to change).
	ValidationExceptionFieldCodeInvalidValue ValidationExceptionFieldCode = "INVALID_VALUE"
	// The member does not apply to this asset's category — today SendMode or
	// ScheduledSendAt on an asset that has no send.
	ValidationExceptionFieldCodeNotSupportedForCategory ValidationExceptionFieldCode = "NOT_SUPPORTED_FOR_CATEGORY"
	// A campaign's recipient list is not UTF-8 text — a UTF-16 file, for instance.
	// Save it as UTF-8 CSV.
	ValidationExceptionFieldCodeRecipientListNotUtf8 ValidationExceptionFieldCode = "RECIPIENT_LIST_NOT_UTF8"
	// The field shows a value of the partner's AWS Partner Central profile, named by
	// the field's PartnerProfileField , so an asset cannot override it. Change it in
	// Partner Central instead.
	ValidationExceptionFieldCodeFieldFromPartnerProfile ValidationExceptionFieldCode = "FIELD_FROM_PARTNER_PROFILE"
	// The image a CampaignAssetImage names cannot be copied: no image field holding
	// an image was found at that source among your assets. The message says which part
	// did not resolve.
	ValidationExceptionFieldCodeCopySourceInvalid ValidationExceptionFieldCode = "COPY_SOURCE_INVALID"
	// A campaign's SenderEmail is not on the domain of the partner's alliance lead
	// email in AWS Partner Central. The domain must match exactly, ignoring case; a
	// subdomain does not.
	ValidationExceptionFieldCodeSenderDomainNotAllianceLead ValidationExceptionFieldCode = "SENDER_DOMAIN_NOT_ALLIANCE_LEAD"
	// The sender's domain has no CNAME record dkim._domainkey. + the domain →
	// dkim._domainkey.md02.com (or dkim.md02.com ), or its DNS could not be checked.
	// Without it the delivery platform rewrites the From address. A shared mail
	// provider's domain can't carry it. May appear with SENDER_DOMAIN_DMARC_MISSING ,
	// as two entries naming SenderEmail .
	ValidationExceptionFieldCodeSenderDomainDkimMissing ValidationExceptionFieldCode = "SENDER_DOMAIN_DKIM_MISSING"
	// The sender's domain has no DMARC record, a single TXT record at _dmarc. + the
	// domain starting v=DMARC1 with a p tag of none , quarantine or reject (the
	// minimum is v=DMARC1; p=none; ), or its DNS could not be checked. Without it the
	// delivery platform rewrites the From address. A shared mail provider's domain
	// can't carry it. May appear with SENDER_DOMAIN_DKIM_MISSING , as two entries
	// naming SenderEmail .
	ValidationExceptionFieldCodeSenderDomainDmarcMissing ValidationExceptionFieldCode = "SENDER_DOMAIN_DMARC_MISSING"
	// A badge needs the partner's primary AWS Partner path to be at stage Validated
	// or Differentiated. Below that, a campaign shows no badge at all, so PartnerBadge
	// is refused and nothing is uploaded.
	ValidationExceptionFieldCodePartnerBadgeNotEligible ValidationExceptionFieldCode = "PARTNER_BADGE_NOT_ELIGIBLE"
)

